package com.ruoyi.lottery.service;
import java.util.Locale;
public class ImageUploadPolicy {public void validate(String name,String mime,byte[] head,long size){if(size>5L*1024*1024)throw new IllegalArgumentException("图片大小不能超过5MB");String n=name==null?"":name.toLowerCase(Locale.ROOT);boolean jpg=n.endsWith(".jpg")||n.endsWith(".jpeg"),png=n.endsWith(".png");if(!jpg&&!png)throw new IllegalArgumentException("只允许上传 JPG 或 PNG 图片");if(jpg&&!("image/jpeg".equalsIgnoreCase(mime)))throw new IllegalArgumentException("图片类型不合法");if(png&&!("image/png".equalsIgnoreCase(mime)))throw new IllegalArgumentException("图片类型不合法");boolean jpgHead=head.length>=3&&(head[0]&255)==255&&(head[1]&255)==216&&(head[2]&255)==255;boolean pngHead=head.length>=8&&(head[0]&255)==137&&head[1]==80&&head[2]==78&&head[3]==71&&head[4]==13&&head[5]==10&&head[6]==26&&head[7]==10;if(jpg&&!jpgHead||png&&!pngHead)throw new IllegalArgumentException("图片文件头不合法");}}
